<script setup>
import {nextTick,onBeforeUnmount,ref,watch} from 'vue'
import {useRoute} from 'vue-router'
import {Bell,Plus} from '@lucide/vue'
import {api} from '../api'
import {formatDate} from '../utils/assignments'
const props=defineProps({course:{type:Object,required:true}}),route=useRoute()
const items=ref([]),canManage=ref(false),loading=ref(true),saving=ref(false),error=ref(''),notice=ref(''),form=ref(null)
let generation=0
async function load(){const current=++generation;loading.value=true;error.value='';try{const result=await api(`/courses/${props.course.id}/announcements`);if(current!==generation)return;items.value=result.items;canManage.value=result.canManage}catch(e){if(current===generation)error.value=e.message}finally{if(current===generation)loading.value=false}}
function edit(item){notice.value='';form.value=item?{id:item.id,title:item.title,body:item.body,status:item.status,expectedVersion:item.version}:{title:'',body:'',status:'draft'}}
async function save(){saving.value=true;error.value='';const {id,...body}=form.value;try{await api(`/courses/${props.course.id}/announcements${id?'/'+id:''}`,{method:id?'PUT':'POST',body});form.value=null;notice.value='公告已儲存。';await load()}catch(e){error.value=e.message}finally{saving.value=false}}
watch(()=>props.course.id,()=>{items.value=[];form.value=null;canManage.value=false;load()},{immediate:true})
watch(()=>[route.query.announcement,items.value],async()=>{await nextTick();if(route.query.announcement)document.getElementById(`announcement-${route.query.announcement}`)?.scrollIntoView?.({block:'start'})})
onBeforeUnmount(()=>generation++)
</script>
<template><section class="surface announcement-panel"><header><div><h2><Bell :size="20"/>課程公告</h2><p class="muted">{{course.title}} 的教學提醒與最新消息。</p></div><button v-if="canManage" class="button primary" aria-label="新增課程公告" @click="edit()"><Plus :size="16"/>新增公告</button></header><p v-if="error" class="error-box" role="alert">{{error}} <button v-if="!form" class="button secondary" @click="load">重新載入</button></p><p v-if="notice" class="success-box" role="status">{{notice}}</p><form v-if="form" class="announcement-editor" @submit.prevent="save"><fieldset :disabled="saving"><legend>{{form.id?'編輯公告':'新增公告'}}</legend><label>標題<input v-model="form.title" aria-label="公告標題" required maxlength="200"/></label><label>內容<textarea v-model="form.body" required maxlength="16000" rows="6"/></label><label>發布狀態<select v-model="form.status"><option value="draft">草稿（僅教學團隊）</option><option value="published">發布給本課學生</option></select></label><div class="editor-actions"><button class="button primary">{{saving?'儲存中…':'儲存公告'}}</button><button type="button" class="button secondary" @click="form=null">取消</button></div></fieldset></form><p v-if="loading" role="status">正在載入公告…</p><p v-else-if="!items.length&&!error" class="empty-inline">目前沒有課程公告。</p><div v-else class="announcements"><article v-for="item in items" :id="`announcement-${item.id}`" :key="item.id" :class="{selected:route.query.announcement===item.id}"><div class="announcement-heading"><h3>{{item.title}}</h3><span v-if="item.status==='draft'" class="status-badge">草稿</span><button v-if="canManage" class="button secondary" @click="edit(item)">編輯公告</button></div><p class="announcement-meta">{{item.authorName}} · {{formatDate(item.publishedAt||item.updatedAt||item.createdAt)}}</p><p class="announcement-body">{{item.body}}</p></article></div></section></template>
<style scoped>
.announcement-panel{padding:24px}.announcement-panel>header{display:flex;justify-content:space-between;align-items:flex-start;gap:16px;margin-bottom:20px}.announcement-panel h2{display:flex;gap:8px;align-items:center;font-size:20px}.announcement-panel .muted{font-size:12px;margin-top:8px}.announcement-panel h2 svg{color:var(--accent)}.announcement-editor{padding:20px;border:1px solid var(--line);border-radius:10px;margin:20px 0}.announcement-editor fieldset{border:0;display:grid;gap:14px;padding:0;min-width:0}.announcement-editor label{display:grid;gap:7px}.editor-actions{display:flex;gap:8px}.announcements article{padding:22px 0;border-top:1px solid var(--line);scroll-margin-top:20px}.announcements article.selected{border-left:3px solid var(--accent);padding-left:15px}.announcement-heading{display:flex;align-items:center;gap:12px;flex-wrap:wrap}.announcement-heading h3{font-size:17px;overflow-wrap:anywhere}.announcement-heading button{margin-left:auto}.announcement-meta{font-size:12px;color:var(--muted);margin:10px 0}.announcement-body{white-space:pre-wrap;line-height:1.9;overflow-wrap:anywhere}@media(max-width:650px){.announcement-panel{padding:18px}.announcement-panel>header{flex-wrap:wrap}.announcement-editor{padding:14px}}
</style>
